from pathlib import Path
import os,json,subprocess,signal,time,shutil
root=Path('/tmp/textbook-vscode-gui');root.mkdir(exist_ok=True)
project=root/'project';project.mkdir(exist_ok=True)
source=Path('/home/mijiao/Apps/Tutorial4New/01-基础通识/examples/ide-demo')
for name in ['main.cpp','CMakeLists.txt']:shutil.copy2(source/name,project/name)
user=root/'user-data';(user/'User').mkdir(parents=True,exist_ok=True)
settings={'workbench.startupEditor':'none','workbench.colorTheme':'Default Light Modern','update.mode':'none','extensions.autoUpdate':False,'extensions.autoCheckUpdates':False,'telemetry.telemetryLevel':'off','cmake.useCMakePresets':'never','cmake.configureOnOpen':False,'cmake.buildDirectory':'${workspaceFolder}/build-vscode'}
(user/'User/settings.json').write_text(json.dumps(settings,indent=2))
fd_read,fd_write=os.pipe()
xvfb=subprocess.Popen(['Xvfb','-displayfd',str(fd_write),'-screen','0','1600x1000x24'],pass_fds=(fd_write,),start_new_session=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
os.close(fd_write);display=os.read(fd_read,100).decode().strip();os.close(fd_read)
env=dict(os.environ,DISPLAY=':'+display,QT_QPA_PLATFORM='xcb',XDG_CONFIG_HOME=str(root/'xdg-config'),XDG_CACHE_HOME=str(root/'xdg-cache'),XDG_STATE_HOME=str(root/'xdg-state'))
env.pop('WAYLAND_DISPLAY',None);env['XDG_SESSION_TYPE']='x11'
log=(root/'code.txt').open('w')
code=subprocess.Popen(['dbus-run-session','--','/run/host/usr/share/code/code','--user-data-dir',str(user),'--shared-data-dir',str(root/'shared-data'),'--extensions-dir','/home/mijiao/.vscode/extensions','--locale','en','--disable-gpu','--ozone-platform=x11','--new-window','--goto',str(project/'main.cpp')+':11',str(project)],env=env,start_new_session=True,stdout=log,stderr=subprocess.STDOUT)
def run(args):return subprocess.run(args,env=env,check=True,capture_output=True,text=True).stdout
def shot(name):
 run(['xwd','-root','-silent','-out',str(root/(name+'.xwd'))]);print(json.dumps({'snapshot':name,'path':str(root/(name+'.xwd'))}),flush=True)
try:
 time.sleep(8);print(json.dumps({'ready':True,'display':display,'folder':str(root)}),flush=True);shot('startup')
 for line in __import__('sys').stdin:
  item=json.loads(line)
  if item.get('quit'):break
  if 'command' in item:
   run(['xdotool','key','ctrl+shift+p']);time.sleep(.3);run(['xdotool','type','--clearmodifiers',item['command']]);time.sleep(.7);run(['xdotool','key','Return'])
  if 'keys' in item:run(['xdotool','key',*item['keys'].split()])
  if 'text' in item:run(['xdotool','type','--clearmodifiers',item['text']])
  time.sleep(item.get('wait',1));shot(item['name'])
finally:
 for proc in [code,xvfb]:
  if proc.poll() is None:
   os.killpg(proc.pid,signal.SIGTERM)
   try:proc.wait(timeout=8)
   except subprocess.TimeoutExpired:os.killpg(proc.pid,signal.SIGKILL);proc.wait()
 log.close()

